from flask import Flask, Blueprint, jsonify, request

# In-memory "database" for demonstration purposes
_users = {
    1: {"id": 1, "name": "Alice"},
    2: {"id": 2, "name": "Bob"},
}
_next_id = 3

# ---------------------------------------------------------------------------
# Users component (Blueprint) - modular set of routes for user management
# ---------------------------------------------------------------------------
users_bp = Blueprint("users", __name__)


@users_bp.get("/")
def list_users():
    return jsonify(list(_users.values()))


@users_bp.get("/<int:user_id>")
def get_user(user_id):
    user = _users.get(user_id)
    if user is None:
        return jsonify({"error": "User not found"}), 404
    return jsonify(user)


@users_bp.post("/")
def create_user():
    global _next_id
    data = request.get_json(silent=True) or {}
    name = data.get("name")
    if not name:
        return jsonify({"error": "'name' is required"}), 400

    user = {"id": _next_id, "name": name}
    _users[_next_id] = user
    _next_id += 1
    return jsonify(user), 201


@users_bp.put("/<int:user_id>")
def update_user(user_id):
    user = _users.get(user_id)
    if user is None:
        return jsonify({"error": "User not found"}), 404

    data = request.get_json(silent=True) or {}
    name = data.get("name")
    if name:
        user["name"] = name
    return jsonify(user)


@users_bp.delete("/<int:user_id>")
def delete_user(user_id):
    if user_id not in _users:
        return jsonify({"error": "User not found"}), 404
    del _users[user_id]
    return "", 204


# ---------------------------------------------------------------------------
# Main application - attaches the users component under the "/users" prefix
# ---------------------------------------------------------------------------
def create_app():
    app = Flask(__name__)

    @app.get("/")
    def index():
        return jsonify({"message": "Welcome to the main application"})

    app.register_blueprint(users_bp, url_prefix="/users")

    return app


app = create_app()

if __name__ == "__main__":
    app.run(debug=True)

